import pytest

def apply_discount(price: float, code: str) -> float:
    if code == "SAVE10":
        return price * 0.9
    elif code == "SAVE20":
        return price * 0.8
    else:
        return price

def test_save10():
    assert apply_discount(100.0, "SAVE10") == 90.0

def test_save20():
    assert apply_discount(100.0, "SAVE20") == 80.0

def test_unknown_code():
    assert apply_discount(100.0, "INVALID") == 100.0

def test_empty_code():
    assert apply_discount(50.0, "") == 50.0

